use super::*;
use crate::model::Partner;
use chrono::{Datelike,TimeZone};
use std::collections::{BTreeMap,BTreeSet};
fn action(v:serde_json::Value)->Action{serde_json::from_value(v).unwrap()}
fn value(g:&Game)->serde_json::Value{serde_json::to_value(g).unwrap()}
fn wealthy()->Game{let mut g=Game::demo();g.earned=100_000_000_000;g.active.as_mut().unwrap().progress=0;g}
#[test]fn every_normal_edge_and_collection(){let c=Catalog::load();let mut checked=0;for species in c.species.values(){for target in c.next(species.id).into_iter().filter(|id|c.normal(species.id,*id)){let mut g=Game::default();g.active=Some(Partner{species_id:species.id,path:vec![species.id],..Default::default()});g.collected.insert(species.id);g.select(target,&c).unwrap();let cost=g.threshold(&c);g.grow(cost-1,&c);assert_eq!(g.active.as_ref().unwrap().species_id,species.id);g.grow(8,&c);assert_eq!(g.active.as_ref().unwrap().species_id,target);assert_eq!(g.progress(),7);assert!(g.collected.contains(&target));g.validate(&c).unwrap();checked+=1}}assert!(checked>300)}
#[test]fn every_special_rule_conditions_and_atomic_consumption(){let c=Catalog::load();let mut kinds=BTreeSet::new();for r in c.rules.iter().filter(|r|["fusion","item","buff"].contains(&r.kind.as_str())){let mut g=wealthy();g.collected.remove(&r.target);g.collected.remove(&r.source);for id in &r.ingredients{g.collected.remove(id);}g.inventory.clear();assert!(!g.eligible(r,0),"negative {}->{}",r.source,r.target);g.collected.insert(r.source);g.collected.extend(r.ingredients.iter().copied());if let Some(item)=&r.item{g.inventory.insert(item.clone(),2);}let today=r.daily_tokens.unwrap_or(0);assert!(g.eligible(r,today));if r.kind=="buff"{assert!(!g.eligible(r,today-1))}let active=g.active.clone();let collected=g.collected.clone();g.special(r.target,today,&c).unwrap();assert_eq!(serde_json::to_value(&g.active).unwrap(),serde_json::to_value(&active).unwrap());assert!(g.collected.is_superset(&collected));assert!(g.collected.contains(&r.target));if let Some(item)=&r.item{assert_eq!(g.inventory[item],1)}let before=value(&g);assert!(g.special(r.target,today,&c).is_err());assert_eq!(value(&g),before);g.validate(&c).unwrap();kinds.insert(r.kind.clone());}assert_eq!(kinds.len(),3)}
#[test]fn purchase_quantity_limits_and_price_scales(){for scale in [0.1,0.5,1.,2.]{for item in model::shop(){let mut g=wealthy();g.settings.shop_difficulty=scale;g.inventory.clear();let price=g.price(&item);g.buy_count(&item.id,3).unwrap();assert_eq!(g.inventory[&item.id],3);assert_eq!(g.spent,price*3);for n in [0,1000,u32::MAX]{let before=value(&g);assert!(g.buy_count(&item.id,n).is_err());assert_eq!(value(&g),before)}g.inventory.insert(item.id.clone(),999);let before=value(&g);assert!(g.buy_count(&item.id,1).is_err());assert_eq!(value(&g),before)}}}
#[test]fn insufficient_money_and_unknown_item_are_atomic(){let mut g=Game::default();for id in ["rareCandy","missing"]{let before=value(&g);assert!(g.buy_count(id,1).is_err());assert_eq!(value(&g),before)}}
#[test]fn egg_purchase_preserves_notebook_and_stored(){let c=Catalog::load();let mut g=wealthy();g.stored=g.active.clone();let owned=g.collected.clone();let stored=serde_json::to_value(&g.stored).unwrap();g.buy_egg(&c).unwrap();assert!(g.active.is_none());assert_eq!(g.egg_progress,0);assert_eq!(g.collected,owned);assert_eq!(serde_json::to_value(&g.stored).unwrap(),stored);assert_eq!(g.capture_log[0].status,"released");assert_eq!(g.spent,1_000_000_000);let before=value(&g);assert!(g.buy_egg(&c).is_err());assert_eq!(value(&g),before)}
#[test]fn no_pendant_or_invalid_count_never_consumes(){let c=Catalog::load();let mut g=wealthy();g.inventory.insert("rareCandy".into(),2);for count in [0,3,u32::MAX]{let before=value(&g);assert!(g.pendant_count(count,&c).is_err());assert_eq!(value(&g),before)}g.active=None;let before=value(&g);assert!(g.pendant_count(1,&c).is_err());assert_eq!(value(&g),before)}
#[test]fn graduation_requires_full_final_gauge(){let c=Catalog::load();let id=c.species.keys().copied().find(|id|c.next(*id).into_iter().all(|n|!c.normal(*id,n))).unwrap();let mut g=wealthy();g.active=Some(Partner{species_id:id,path:vec![id],..Default::default()});g.collected.insert(id);let cost=g.threshold(&c);g.grow(cost-1,&c);assert!(g.active.is_some());g.grow(1,&c);assert!(g.active.is_none());assert_eq!(g.capture_log[0].path,vec![id]);assert_eq!(g.capture_log[0].status,"graduated")}
#[test]fn continued_final_form_must_finish_its_gauge_before_restore(){let c=Catalog::load();let (from,to)=c.species.keys().copied().filter(|id|*id!=2003).find_map(|from|c.next(from).into_iter().filter(|to|c.normal(from,*to)).find(|to|c.next(*to).into_iter().all(|n|!c.normal(*to,n))).map(|to|(from,to))).unwrap();let mut g=wealthy();g.collected=c.species.keys().copied().filter(|id|*id!=to).collect();let stored=g.active.clone();g.special_collected.insert(from);g.continue_training(from,&c).unwrap();g.grow(g.threshold(&c),&c);assert_eq!(g.active.as_ref().unwrap().species_id,to,"new final form must remain active at zero final-stage progress");assert!(g.stored.is_some());g.grow(g.threshold(&c)-1,&c);assert_eq!(g.active.as_ref().unwrap().species_id,to);g.grow(1,&c);assert_eq!(serde_json::to_value(&g.active).unwrap(),serde_json::to_value(&stored).unwrap());assert!(g.stored.is_none())}
#[test]fn pendant_batch_preserves_unused_items_on_restoration(){let c=Catalog::load();let terminal=c.species.keys().copied().find(|id|*id!=2003&&c.next(*id).into_iter().all(|n|!c.normal(*id,n))).unwrap();let mut g=wealthy();g.stored=g.active.clone();g.active=Some(Partner{species_id:terminal,path:vec![terminal],progress:1_000_000_000,..Default::default()});g.collected.insert(terminal);g.inventory.insert("rareCandy".into(),5);g.pendant_count(5,&c).unwrap();assert_eq!(g.inventory["rareCandy"],4);assert_eq!(g.active.as_ref().unwrap().species_id,2003)}
#[test]fn old_settings_migrate_and_all_fields_roundtrip(){let c=Catalog::load();let mut json=value(&wealthy());for key in ["language","representativeId","refreshInterval","animationQuality","limitDisplayMode"]{json["settings"].as_object_mut().unwrap().remove(key);}let mut g:Game=serde_json::from_value(json).unwrap();assert_eq!(g.settings.language,"ko");assert_eq!(g.settings.refresh_interval,60);for language in ["ko","en"]{for interval in [0,60,120,300,900]{for quality in ["powerSaver","balanced","smooth"]{let mut settings=g.settings.clone();settings.language=language.into();settings.refresh_interval=interval;settings.animation_quality=quality.into();settings.representative_id=Some(2001);settings.limit_display_mode="remaining".into();apply(&mut g,action(serde_json::json!({"kind":"settings","settings":settings})),0,&c).unwrap();let restored:Game=serde_json::from_value(value(&g)).unwrap();restored.validate(&c).unwrap();assert_eq!(restored.settings.refresh_interval,interval);assert_eq!(restored.settings.language,language)}}}}
#[test]fn invalid_settings_rejected(){let c=Catalog::load();for (key,val) in [("language",serde_json::json!("xx")),("refreshInterval",serde_json::json!(1)),("representativeId",serde_json::json!(999999)),("difficulty",serde_json::json!(0)),("shopDifficulty",serde_json::json!(3)),("animationQuality",serde_json::json!("invalid")),("limitDisplayMode",serde_json::json!("invalid"))]{let mut g=wealthy();let mut settings=serde_json::to_value(&g.settings).unwrap();settings[key]=val;assert!(apply(&mut g,action(serde_json::json!({"kind":"settings","settings":settings})),0,&c).is_err(),"{key}")}}
#[test]fn save_roundtrip_and_backup(){let c=Catalog::load();let dir=tempfile::tempdir().unwrap();let file=dir.path().join("state.json");let mut g=wealthy();save(&file,&g).unwrap();let before=fs::read(&file).unwrap();g.buy_count("rareCandy",1).unwrap();save(&file,&g).unwrap();assert_eq!(fs::read(file.with_extension("json.bak")).unwrap(),before);let loaded:Game=serde_json::from_slice(&fs::read(file).unwrap()).unwrap();loaded.validate(&c).unwrap();assert_eq!(value(&loaded),value(&g))}
fn line(day:chrono::NaiveDate,id:&str,input:u64,output:u64,read:u64,write:u64)->String{let timestamp=chrono::Local.from_local_datetime(&day.and_hms_opt(12,0,0).unwrap()).unwrap().to_rfc3339();serde_json::json!({"type":"assistant","timestamp":timestamp,"message":{"id":id,"usage":{"input_tokens":input,"output_tokens":output,"cache_read_input_tokens":read,"cache_creation_input_tokens":write}}}).to_string()}
#[test]fn log_month_week_timezone_duplicate_roots_and_append(){let dir=tempfile::tempdir().unwrap();let file=dir.path().join("session.jsonl");let today=chrono::Local::now().date_naive();let past=today-chrono::Duration::days(1);fs::write(&file,format!("{}\n{}\n",line(past,"past",10,20,30,40),line(today,"today",100,200,300,400))).unwrap();let paths=BTreeMap::from([("Claude Code".into(),vec![dir.path().to_string_lossy().into(),dir.path().to_string_lossy().into()])]);let mut reader=Reader::default();let usage=reader.scan_paths(paths.clone());assert_eq!(usage.today(),1000);let p=&usage.providers[0];assert_eq!(p.files,1);assert_eq!(p.month,1000+if past.month()==today.month(){100}else{0});assert_eq!(p.week,1000+if today.weekday().num_days_from_monday()>0{100}else{0});assert_eq!(p.today.cache_read,300);assert_eq!(p.today.cache_write,400);use std::io::Write;let mut f=fs::OpenOptions::new().append(true).open(&file).unwrap();writeln!(f,"{}",line(today,"today",110,220,330,440)).unwrap();writeln!(f,"{}",line(today,"second",1,2,3,4)).unwrap();write!(f,"{{").unwrap();drop(f);let next=reader.scan_paths(paths);assert_eq!(next.today(),1110);assert_eq!(next.providers[0].files,1)}
#[test]fn ledger_baseline_restart_and_provider_isolation(){let c=Catalog::load();let mut g=Game::default();g.observe("Codex","day1",1000,&c);assert_eq!(g.earned,0);g.observe("Codex","day1",1100,&c);g.observe("Claude Code","day1",5000,&c);assert_eq!(g.earned,100);let mut restarted:Game=serde_json::from_value(value(&g)).unwrap();restarted.observe("Codex","day1",1100,&c);restarted.observe("Codex","day1",900,&c);restarted.observe("Codex","day1",1150,&c);restarted.observe("Claude Code","day1",5050,&c);assert_eq!(restarted.earned,200);restarted.observe("Codex","day2",50,&c);assert_eq!(restarted.earned,250)}
#[test]fn ordinary_collection_does_not_unlock_special_continuation(){let c=Catalog::load();let mut g=wealthy();assert!(c.missing(2001,&g.collected,&[]));let before=value(&g);assert!(g.continue_training(2001,&c).is_err());assert_eq!(value(&g),before)}
#[test]fn completion_record_uses_completion_time_not_training_start(){let c=Catalog::load();let mut g=wealthy();g.active.as_mut().unwrap().started_at=Some("2020-01-01T00:00:00+09:00".into());let before=chrono::Local::now().timestamp();g.buy_egg(&c).unwrap();let at=chrono::DateTime::parse_from_rfc3339(g.capture_log[0].caught_at.as_ref().unwrap()).unwrap().timestamp();assert!(at>=before,"released records must be timestamped when released, not when training began")}
#[test]fn legacy_special_records_unlock_continuation_and_are_preserved(){let c=Catalog::load();let id=c.species.keys().copied().find(|id|*id!=2003&&*id!=2001&&c.missing(*id,&Game::demo().collected,&[])).unwrap();let mut g=wealthy();g.collected.insert(id);g.capture_log.push(model::CaptureRecord{id:"legacy-special".into(),species_id:id,path:vec![id],caught_at:None,status:"registered".into()});assert!(g.is_special_collected(id));g.continue_training(id,&c).unwrap();let mut restarted:Game=serde_json::from_value(value(&g)).unwrap();assert!(restarted.is_special_collected(id));restarted.buy_egg(&c).unwrap();assert!(restarted.special_collected.contains(&id))}
#[test]fn ten_thousand_mixed_game_operations_preserve_invariants(){use rand::{Rng,SeedableRng};let c=Catalog::load();let mut rng=rand::rngs::StdRng::seed_from_u64(20261101);let mut g=wealthy();g.earned=100_000_000_000_000;g.observe("stress","today",0,&c);let items=model::shop();let mut counter=0u64;for _ in 0..10000{match rng.gen_range(0..11){0..=3=>{counter+=rng.gen_range(1..=100_000_000);g.observe("stress","today",counter,&c)},4=>{let item=&items[rng.gen_range(0..items.len())];let _=g.buy_count(&item.id,rng.gen_range(1..=3));},5=>{let n=g.inventory.get("rareCandy").copied().unwrap_or(0).min(3);if n>0{let _=g.pendant_count(n,&c);}},6=>{let _=g.buy_egg(&c);},7=>{if let Some(target)=c.rules.iter().find(|r|!g.collected.contains(&r.target)&&g.eligible(r,counter)).map(|r|r.target){g.special(target,counter,&c).unwrap()}},8=>{if let Some(id)=g.special_collected.iter().copied().find(|id|c.missing(*id,&g.collected,&[])){let _=g.continue_training(id,&c);}},9=>{if g.active.is_some()&&g.stored.is_some(){apply(&mut g,action(serde_json::json!({"kind":"swap"})),counter,&c).unwrap()}},_=>{g.difficulty(rng.gen_range(1..=20)as f64/10.,&c).unwrap()}}g.validate(&c).unwrap();assert!(g.spent<=g.earned);assert!(g.active.as_ref().map(|p|g.collected.contains(&p.species_id)).unwrap_or(true));}}